 \u2014 RFP: Request for proposal to venues/vendors."], ["Force majeure","Profession term \u2014 Force majeure: Contract clause for unforeseeable events."], ["Day-of coordination","Profession term \u2014 Day-of coordination: Execution-only service."], ["Full planning","Profession term \u2014 Full planning: End-to-end planning service."], ["Vendor meal","Profession term \u2014 Vendor meal: Feeding the working crew."], ["Green room","Profession term \u2014 Green room: Private waiting space for talent/speakers."], ["Registration","Profession term \u2014 Registration: Check-in operations."], ["Swag","Profession term \u2014 Swag: Branded giveaways."], ["Post-con","Profession term \u2014 Post-con: Post-convention debrief."], ["ROI","Profession term \u2014 ROI: Return on investment measurement."]];
function ask(n){var out=[],seen={};n=Math.min(n,ITEMS.length);for(var k=0;k<n;k++){var it=ITEMS[(Math.random()*ITEMS.length)|0];out.push("Q"+(k+1)+": "+it[0]+"\nA"+(k+1)+": "+it[1]);}return out.join("\n\n");}
function lookup(q){q=String(q).toLowerCase();var h=[];for(var i=0;i<ITEMS.length;i++){if((ITEMS[i][0]+" "+ITEMS[i][1]).toLowerCase().indexOf(q)>=0)h.push(ITEMS[i][0]+" — "+ITEMS[i][1]);}return h.length?h.join("\n"):"no match for "+q;}
